/* SHIFTREX demo: no server connection, no real authentication, no personal data collection. */
(()=>{
'use strict';
const ROLE=document.body.dataset.app==='admin'?'admin':'member';
const KEY='shiftrex-demo-state-v1',VERSION=1;
const root=document.getElementById('app');
const $=(id)=>document.getElementById(id);
const pad=n=>String(n).padStart(2,'0');
const fmtDate=(date)=>`${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}`;
const fromISO=s=>new Date(`${s}T12:00:00`);
const addDays=(iso,n)=>{let d=fromISO(iso);d.setDate(d.getDate()+n);return fmtDate(d)};
const dayToday=()=>{let p=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());let obj=Object.fromEntries(p.map(x=>[x.type,x.value]));return `${obj.year}-${obj.month}-${obj.day}`};
const TODAY=dayToday();
const monthOf=iso=>iso.slice(0,7);
const niceDate=iso=>iso?`${Number(iso.slice(5,7))}月${Number(iso.slice(8,10))}日`: '—';
const fullDate=iso=>iso?`${iso.slice(0,4)}年${niceDate(iso)}`:'—';
const dayName=iso=>'日月火水木金土'[fromISO(iso).getDay()];
const money=v=>'¥'+Number(v||0).toLocaleString('ja-JP');
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=escapeHTML;
const uid=prefix=>`${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
function seed(){const plus=n=>addDays(TODAY,n);return {version:VERSION,members:[{id:'STX-0001',name:'山田 太郎',kana:'ヤマダ タロウ',status:'active',phone:'090-0000-0000',email:'demo.member@example.invalid',joined:TODAY},{id:'STX-0002',name:'佐藤 花子',kana:'サトウ ハナコ',status:'active',phone:'090-0000-0000',email:'sample2@example.invalid',joined:TODAY},{id:'STX-0003',name:'鈴木 健',kana:'スズキ ケン',status:'paused',phone:'090-0000-0000',email:'sample3@example.invalid',joined:TODAY}],menus:[{id:'menu8',name:'8回券',price:52800,count:8,days:70,monthRequired:false,hidden:false},{id:'menu1',name:'単発セッション',price:8000,count:1,days:0,monthRequired:false,hidden:false},{id:'menu0',name:'月会費',price:3000,count:0,days:0,monthRequired:true,hidden:false},{id:'menuF',name:'食事管理',price:11000,count:0,days:0,monthRequired:false,hidden:false}],tickets:[{id:'TK-001',memberId:'STX-0001',menuId:'menu8',total:8,remaining:6,purchased:TODAY,expires:plus(69),source:'DEMO-001'},{id:'TK-002',memberId:'STX-0002',menuId:'menu8',total:8,remaining:4,purchased:TODAY,expires:plus(69),source:'DEMO-002'}],bookings:[{id:'RES-001',memberId:'STX-0001',date:plus(1),time:'10:00',status:'confirmed',ticketId:'TK-001'},{id:'RES-002',memberId:'STX-0002',date:plus(1),time:'14:00',status:'confirmed',ticketId:'TK-002'},{id:'RES-003',memberId:'STX-0001',date:plus(2),time:'16:00',status:'pending',ticketId:null},{id:'RES-004',memberId:'STX-0001',date:plus(4),time:'11:30',status:'confirmed',ticketId:'TK-001'}],purchases:[{id:'DEMO-001',memberId:'STX-0001',menuId:'menu8',date:TODAY,price:52800,targetMonth:'',payments:[{id:'PMT-001',amount:52800,date:TODAY,method:'現金'}],canceled:false,issuedTicketId:'TK-001'},{id:'DEMO-002',memberId:'STX-0002',menuId:'menu8',date:TODAY,price:52800,targetMonth:'',payments:[{id:'PMT-002',amount:52800,date:TODAY,method:'現金'}],canceled:false,issuedTicketId:'TK-002'}],notices:[{id:'N-01',title:'SHIFTREXへようこそ',body:'予約・チケットの確認は、このアプリから行えます。',date:TODAY}],changes:[],logs:[],settings:{publishedMonths:[monthOf(TODAY)],open:'09:00',close:'21:00',backupFrequency:'daily',bookingCutoff:3,modeBySlot:{[`${plus(2)} 16:00`]:'approval'}},alerts:[]};}
function read(){try{let v=JSON.parse(localStorage.getItem(KEY));if(v&&v.version===VERSION&&Array.isArray(v.members)&&Array.isArray(v.bookings))return v;}catch(e){}return seed()}
let db=read();const save=()=>localStorage.setItem(KEY,JSON.stringify(db));save();
let tab='home',calendarView='month',adminView='day',selectedDate=TODAY,viewMonth=monthOf(TODAY),memberId='STX-0001',memberSearch='',ticketSearch='',memberFilter='all',ticketFilter='all',modalHTML='',toastText='',pendingRestore=null;
const who=id=>db.members.find(x=>x.id===id)||{id,name:'不明な会員',status:'left'};
const menu=id=>db.menus.find(x=>x.id===id)||{id,name:'削除済みメニュー',price:0,count:0,days:0};
const isPastCutoff=(date,time)=>Date.now()+Number(db.settings.bookingCutoff||0)*3600000>Date.parse(`${date}T${time}:00+09:00`);
const statBadge=status=>({confirmed:'<span class="badge good">確定</span>',pending:'<span class="badge warn">承認待ち</span>',canceled:'<span class="badge bad">キャンセル</span>',declined:'<span class="badge bad">却下</span>',done:'<span class="badge good">実施済み</span>',absent:'<span class="badge bad">欠席</span>'}[status]||`<span class="badge">${escapeHTML(status)}</span>`);
const memberBadge=s=>s==='active'?'<span class="badge good">在籍</span>':s==='paused'?'<span class="badge warn">休会</span>':'<span class="badge bad">退会</span>';
function validTicket(t,date){return t.remaining>0&&(!t.expires||date<=t.expires)&&(date>=t.purchased)}
function usable(id,date){return db.tickets.filter(t=>t.memberId===id&&validTicket(t,date)).sort((a,b)=>(a.expires||'9999').localeCompare(b.expires||'9999'))}
function slotConflict(date,time,omit){let b=timeToNum(time),e=b+60;return db.bookings.some(r=>r.id!==omit&&r.date===date&&['confirmed','done','absent'].includes(r.status)&&b<timeToNum(r.time)+60&&e>timeToNum(r.time))}
function timeToNum(t){let [h,m]=t.split(':').map(Number);return h*60+m}
function numToTime(n){return `${pad(Math.floor(n/60))}:${pad(n%60)}`}
function monthDays(month){let y=+month.slice(0,4),m=+month.slice(5,7),last=new Date(y,m,0).getDate();return Array.from({length:last},(_,i)=>`${month}-${pad(i+1)}`)}
function weekDays(iso){let d=fromISO(iso),offset=(d.getDay()+6)%7;return Array.from({length:7},(_,i)=>addDays(iso,i-offset))}
function moveMonth(n){let d=fromISO(viewMonth+'-01');d.setMonth(d.getMonth()+n);viewMonth=monthOf(fmtDate(d));selectedDate=`${viewMonth}-01`}
function activeBookings(mid){return db.bookings.filter(b=>b.memberId===mid&&b.date>=TODAY&&['confirmed','pending'].includes(b.status)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))}
function sortBookings(items){return items.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))}
function adminAlertsCount(){return db.bookings.filter(b=>b.status==='pending').length+db.changes.filter(c=>c.status==='pending').length}
function log(action,description){db.logs.unshift({date:new Date().toISOString(),action,description});db.logs=db.logs.slice(0,150)}
function notify(text){toastText=text;render();setTimeout(()=>{toastText='';let el=$('toast');if(el)el.remove()},2900)}
function setTab(t){tab=t;modalHTML='';render();window.scrollTo(0,0)}
const navMember=[['home','⌂','ホーム'],['booking','▣','予約'],['tickets','▤','チケット'],['profile','◉','マイページ']];
const navAdmin=[['home','⌂','ホーム'],['booking','▣','予約管理'],['members','♙','会員管理'],['tickets','▤','チケット管理'],['settings','⚙','設定']];
function layout(inner){const items=ROLE==='admin'?navAdmin:navMember;root.innerHTML=`<div class="app" data-role="${ROLE}"><header class="topbar"><div class="shell"><a href="/" class="brand" aria-label="SHIFTREXトップに戻る"><span class="brand-logo">SR</span><span><span class="brand-text">SHIFTREX</span><span class="brand-sub">${ROLE==='admin'?'ADMIN CONSOLE':'MEMBER PORTAL'}</span></span></a><div class="top-actions"><span class="demo-label">DEMO</span><button class="icon-btn" data-action="show-alerts" aria-label="お知らせ">♧${ROLE==='admin'&&adminAlertsCount()?'<span class="dot"></span>':''}</button></div></div></header><main class="main shell"><div class="banner"><span>◌</span><span>これはサンプルデータを使用した画面デモです。LINEログイン・本番データベース・プッシュ通知は未接続です。</span></div>${inner}<footer class="footer-note">© SHIFTREX · PROTOTYPE / LOCAL DEMO</footer></main><div class="navwrap"><nav class="tabs" aria-label="下部メニュー">${items.map(([key,ico,label])=>`<button class="navtab ${tab===key?'active':''}" data-tab="${key}" type="button"><span class="navico">${ico}</span><span>${label}</span></button>`).join('')}</nav></div>${modalHTML?`<div class="modal-layer" data-backdrop="true"><div class="modal" role="dialog" aria-modal="true">${modalHTML}</div></div>`:''}${toastText?`<div class="toast" id="toast">${escapeHTML(toastText)}</div>`:''}</div>`;}
function head(title,subtitle,right=''){return `<div class="page-head"><div><div class="eyebrow">${ROLE==='admin'?'SHIFTREX MANAGEMENT':'SHIFTREX MEMBER'}</div><h1 class="page-title">${title}</h1>${subtitle?`<p class="page-desc">${subtitle}</p>`:''}</div>${right}</div>`}
function section(title,action=''){return `<div class="section-head"><h2 class="section-title">${title}</h2>${action}</div>`}
function itemBooking(b,actions=false){return `<div class="item"><div class="item-main"><span class="item-icon">${escapeHTML(b.time.slice(0,2))}</span><div><strong>${ROLE==='admin'?escapeHTML(who(b.memberId).name):`${niceDate(b.date)}（${dayName(b.date)}） ${b.time}`}</strong><small>${ROLE==='admin'?`${niceDate(b.date)}（${dayName(b.date)}） ${b.time}〜${numToTime(timeToNum(b.time)+60)}`:`${b.time}〜${numToTime(timeToNum(b.time)+60)} ・60分`}</small></div></div><div class="item-right">${statBadge(b.status)}${actions?`<button class="btn soft" data-action="booking-detail" data-id="${attr(b.id)}">詳細</button>`:''}</div></div>`}
function memberHome(){const m=who(memberId),next=activeBookings(memberId).find(b=>b.status==='confirmed'),count=db.tickets.filter(t=>t.memberId===memberId).reduce((n,t)=>n+(validTicket(t,TODAY)?t.remaining:0),0),pending=activeBookings(memberId).filter(b=>b.status==='pending');return head('ホーム',`${escapeHTML(m.name)} 様、こんにちは。`)+`<section class="hero"><div><div class="eyebrow">YOUR NEXT SESSION</div><h2>${next?`${niceDate(next.date)}（${dayName(next.date)}） ${next.time}`:'次回の予約はありません'}</h2><p>${next?'次回のトレーニングまで、あと少し。':'ご都合のよい日時からご予約いただけます。'}</p><button class="btn primary" data-tab="booking">予約する <span>↗</span></button></div><div class="hero-art">SR</div></section><div class="stat-grid"><div class="stat"><div class="stat-label">利用可能チケット</div><div class="stat-num">${count}<span class="stat-suffix">回</span></div><div class="stat-foot">有効な残数</div></div><div class="stat"><div class="stat-label">確定予約</div><div class="stat-num">${activeBookings(memberId).filter(b=>b.status==='confirmed').length}<span class="stat-suffix">件</span></div><div class="stat-foot">今後の予約</div></div><div class="stat"><div class="stat-label">承認待ち</div><div class="stat-num">${pending.length}<span class="stat-suffix">件</span></div><div class="stat-foot">申請中</div></div></div><div class="panels"><section class="panel">${section('今後の予約',`<button class="link-btn" data-tab="booking">予約画面へ →</button>`)}<div class="item-list">${activeBookings(memberId).length?activeBookings(memberId).map(b=>itemBooking(b,true)).join(''):'<div class="empty">予約はまだありません。</div>'}</div></section><section class="panel">${section('お知らせ')}<div class="item-list">${db.notices.slice(0,4).map(n=>`<div class="item"><div class="item-main"><span class="item-icon">✦</span><div><strong>${escapeHTML(n.title)}</strong><small>${escapeHTML(n.body)}</small><small>${niceDate(n.date)}</small></div></div></div>`).join('')||'<div class="empty">新しいお知らせはありません。</div>'}</div></section></div>`}
function dateGrid(weekly=false){let ds=weekly?weekDays(selectedDate):monthDays(viewMonth);return `<div class="days">${ds.map(s=>`<button type="button" class="day ${s===selectedDate?'active':''} ${s<TODAY?'unavailable':''}" data-action="select-day" data-date="${s}"><span class="dow">${dayName(s)}</span><span class="date">${Number(s.slice(-2))}</span><span class="day-dot"></span></button>`).join('')}</div>`}
function makeSlots(){let s=db.settings,open=timeToNum(s.open),close=timeToNum(s.close),out=[];for(let n=open;n+60<=close;n+=30){const time=numToTime(n),conflict=slotConflict(selectedDate,time),mode=s.modeBySlot[`${selectedDate} ${time}`]||'instant',published=s.publishedMonths.includes(monthOf(selectedDate));out.push({time,mode,disabled:conflict||selectedDate<TODAY||!published||(ROLE==='member'&&isPastCutoff(selectedDate,time))});}return out}
function memberBooking(){const week=calendarView==='week';return head('予約','60分セッションのご希望日時を選択してください。')+`<section class="panel"><div class="calendar-tools"><div class="monthnav"><button class="square-arrow" data-action="previous-month" aria-label="前の月">‹</button><h3>${viewMonth.slice(0,4)}年${Number(viewMonth.slice(5))}月</h3><button class="square-arrow" data-action="next-month" aria-label="次の月">›</button></div><div class="chips"><button class="chip ${!week?'active':''}" data-action="calendar-view" data-view="month">月</button><button class="chip ${week?'active':''}" data-action="calendar-view" data-view="week">週</button></div></div>${dateGrid(week)}<div class="divider"></div><div class="split-head"><div><h2 class="section-title">${niceDate(selectedDate)}（${dayName(selectedDate)}）</h2><div class="calendar-summary">○ 即時確定 ／ △ 承認制 ／ × 予約不可</div></div><span class="badge">60分 / 30分刻み</span></div>${db.settings.publishedMonths.includes(monthOf(selectedDate))?`<div class="slot-grid">${makeSlots().map(slot=>`<button class="slot" ${slot.disabled?'disabled':''} data-action="select-slot" data-time="${slot.time}"><strong>${slot.disabled?'×':slot.mode==='approval'?'△':'○'} ${slot.time}</strong><small>${slot.disabled?'予約不可':slot.mode==='approval'?'承認制':'即時確定'}</small></button>`).join('')}</div>`:`<div class="empty"><span class="empty-icon">▣</span>この月の予約枠はまだ公開されていません。</div>`}</section><section class="panel" style="margin-top:17px">${section('予約状況')}<div class="item-list">${activeBookings(memberId).length?activeBookings(memberId).map(b=>itemBooking(b,true)).join(''):'<div class="empty">現在の予約・申請はありません。</div>'}</div></section>`}
function memberTickets(){const ts=db.tickets.filter(t=>t.memberId===memberId&&t.total>0);return head('チケット','現在のチケット残数と有効期限を確認できます。')+`<div class="grid2"><div>${ts.length?ts.map(t=>`<div class="ticket"><div class="ticket-top"><div><div class="label">${escapeHTML(menu(t.menuId).name)}</div><div class="count">${t.remaining}<span> / ${t.total}回</span></div></div>${t.expires&&t.expires<TODAY?'<span class="badge bad">期限切れ</span>':t.remaining===0?'<span class="badge">使用済み</span>':'<span class="badge good">利用可能</span>'}</div><div class="ticket-line"></div><div class="ticket-bottom"><span>チケット番号 ${escapeHTML(t.id)}</span><span>期限 ${t.expires?fullDate(t.expires):'設定なし'}</span></div></div>`).join(''):'<div class="panel empty">チケットはまだありません。</div>'}</div><div class="panel">${section('チケット利用ルール')}<div class="reading"><span>予約確定時</span><strong>チケット1回分を消化</strong></div><div class="reading"><span>有効期限</span><strong>セッション実施日で判定</strong></div><div class="reading"><span>複数チケット保有</span><strong>有効期限が近い順</strong></div><p class="note">購入金額・入金状況は会員用アプリには表示されません。</p></div></div>`}
function memberProfile(){const m=who(memberId),ch=db.changes.find(c=>c.memberId===memberId&&c.status==='pending');return head('マイページ','会員情報・登録連絡先を確認できます。')+`<div class="grid2"><section class="panel">${section('会員情報',memberBadge(m.status))}<div class="reading"><span class="muted">会員ID</span><strong>${escapeHTML(m.id)}</strong></div><div class="reading"><span class="muted">氏名</span><strong>${escapeHTML(m.name)}</strong></div><div class="reading"><span class="muted">フリガナ</span><strong>${escapeHTML(m.kana)}</strong></div><div class="reading"><span class="muted">電話番号</span><strong>${escapeHTML(m.phone)}</strong></div><div class="reading"><span class="muted">メールアドレス</span><strong>${escapeHTML(m.email)}</strong></div><div style="margin-top:18px"><button class="btn primary" data-action="request-change">連絡先の変更を申請</button></div>${ch?`<div class="notice" style="margin-top:15px">連絡先変更申請が承認待ちです。<button class="link-btn" data-action="cancel-change" style="display:block;margin-top:8px">申請を取り消す</button></div>`:''}</section><section class="panel">${section('ログインについて')}<p class="muted small">本番では初回招待リンクからLINEアカウントを安全に連携する予定です。</p><div class="divider"></div><p class="note">現在はデモ画面のためLINE認証は行われません。この画面に実際の個人情報を入力しないでください。</p><button class="btn" data-action="reset-demo">デモデータを初期化</button></section></div>`}
function adminHome(){const todayBookings=sortBookings(db.bookings.filter(b=>b.date===TODAY&&b.status==='confirmed')),pend=sortBookings(db.bookings.filter(b=>b.status==='pending')),active=db.members.filter(m=>m.status==='active').length,soon=db.tickets.filter(t=>t.remaining>0&&t.expires&&t.expires>=TODAY&&t.expires<=addDays(TODAY,7)).length;return head('ホーム',`${fullDate(TODAY)}（${dayName(TODAY)}） の管理状況`)+`<div class="stat-grid"><div class="stat"><div class="stat-label">在籍会員</div><div class="stat-num">${active}<span class="stat-suffix">名</span></div><div class="stat-foot">登録 ${db.members.length}名</div></div><div class="stat"><div class="stat-label">本日の確定予約</div><div class="stat-num">${todayBookings.length}<span class="stat-suffix">件</span></div><div class="stat-foot">今後の予約を含む</div></div><div class="stat"><div class="stat-label">承認待ち</div><div class="stat-num">${pend.length}<span class="stat-suffix">件</span></div><div class="stat-foot">期限間近の券 ${soon}件</div></div></div><div class="panels"><div class="stack"><section class="panel">${section('本日の予約一覧',`<button class="link-btn" data-tab="booking">すべて見る →</button>`)}<div class="item-list">${todayBookings.length?todayBookings.map(b=>itemBooking(b,true)).join(''):'<div class="empty">本日の確定予約はありません。</div>'}</div></section><section class="panel">${section(`承認待ちの予約申請`,`${pend.length?`<span class="badge warn">${pend.length}件</span>`:''}`)}<div class="item-list">${pend.length?pend.map(b=>`<div class="item"><div class="item-main"><span class="item-icon">◉</span><div><strong>${escapeHTML(who(b.memberId).name)}</strong><small>${niceDate(b.date)}（${dayName(b.date)}） ${b.time}〜</small></div></div><div class="item-right"><button class="btn soft primary" data-action="approve" data-id="${b.id}">承認</button><button class="btn soft" data-action="decline" data-id="${b.id}">却下</button></div></div>`).join(''):'<div class="empty">承認待ちの申請はありません。</div>'}</div></section></div><div class="stack"><section class="panel">${section('通知・申請')}<div class="item-list">${db.changes.filter(c=>c.status==='pending').map(c=>`<div class="item"><div class="item-main"><span class="item-icon">✎</span><div><strong>${escapeHTML(who(c.memberId).name)}：連絡先変更</strong><small>電話・メールの編集申請</small></div></div><button class="btn soft" data-action="review-change" data-id="${c.id}">確認</button></div>`).join('')||'<div class="empty">未処理の通知はありません。</div>'}</div></section><section class="panel">${section('最近の操作履歴')}<div class="item-list">${db.logs.slice(0,4).map(l=>`<div class="item"><div class="item-main"><span class="item-icon">↺</span><div><strong>${escapeHTML(l.action)}</strong><small>${escapeHTML(l.description)}</small></div></div></div>`).join('')||'<div class="empty">操作履歴はまだありません。</div>'}</div></section></div></div>`}
function adminBooking(){const bookings=sortBookings(db.bookings.filter(b=>adminView==='day'?b.date===selectedDate:adminView==='week'?weekDays(selectedDate).includes(b.date):monthOf(b.date)===viewMonth));return head('予約管理','予約枠・承認申請・確定予約を管理します。',`<button class="btn primary" data-action="create-booking">＋ 予約を追加</button>`)+`<section class="panel"><div class="calendar-tools"><div class="monthnav"><button class="square-arrow" data-action="previous-month">‹</button><h3>${viewMonth.slice(0,4)}年${Number(viewMonth.slice(5))}月</h3><button class="square-arrow" data-action="next-month">›</button></div><div class="chips">${['day','week','month'].map((v,i)=>`<button class="chip ${adminView===v?'active':''}" data-action="admin-view" data-view="${v}">${['日','週','月'][i]}</button>`).join('')}</div></div>${dateGrid(adminView==='week')}<div class="divider"></div>${section(adminView==='day'?`${niceDate(selectedDate)}の予約`:adminView==='week'?'今週の予約':'今月の予約',`<span class="badge">${bookings.length}件</span>`)}<div class="item-list">${bookings.length?bookings.map(b=>itemBooking(b,true)).join(''):'<div class="empty">この期間の予約はありません。</div>'}</div></section><section class="panel" style="margin-top:17px">${section('個別の予約枠設定')}<p class="muted small">${niceDate(selectedDate)}の承認方式を変更できます。公開済みの月のみ、会員が予約できます。</p><div class="toolbar"><span class="badge ${db.settings.publishedMonths.includes(monthOf(selectedDate))?'good':'warn'}">${db.settings.publishedMonths.includes(monthOf(selectedDate))?'公開中':'未公開'}</span><button class="btn soft" data-action="toggle-publication">${db.settings.publishedMonths.includes(monthOf(selectedDate))?'今月の公開を取り消す':'この月を公開する'}</button></div><div class="slot-grid">${makeSlots().slice(0,16).map(s=>`<button class="slot" data-action="toggle-mode" data-time="${s.time}" ${selectedDate<TODAY?'disabled':''}><strong>${s.time}</strong><small>${s.mode==='approval'?'△ 承認制':'○ 即時確定'}</small></button>`).join('')}</div><p class="note">※枠の公開・承認方式はデモで保存されます。本番プッシュ通知は未接続です。</p></section>`}
function adminMembers(){let list=db.members.filter(m=>(m.name+m.kana+m.id).toLowerCase().includes(memberSearch.toLowerCase())&&(memberFilter==='all'||m.status===memberFilter));return head('会員管理','会員情報・申請・購入とチケットを確認します。',`<button class="btn primary" data-action="create-member">＋ 会員を登録</button>`)+`<section class="panel"><div class="toolbar"><input class="search" id="member-search" placeholder="氏名・会員IDで検索" value="${attr(memberSearch)}"><div class="chips">${[['all','すべて'],['active','在籍'],['paused','休会'],['left','退会']].map(([v,t])=>`<button class="chip ${memberFilter===v?'active':''}" data-action="member-filter" data-filter="${v}">${t}</button>`).join('')}</div></div><div class="stack">${list.map(m=>`<div class="member-card"><div class="card-left"><span class="profile-circle">${escapeHTML(m.name.split(' ')[0].slice(0,1))}</span><div><h3>${escapeHTML(m.name)}　${memberBadge(m.status)}</h3><p>${escapeHTML(m.id)} ｜ ${escapeHTML(m.kana)}</p></div></div><button class="btn soft" data-action="member-detail" data-id="${m.id}">詳細 →</button></div>`).join('')||'<div class="empty">該当する会員がいません。</div>'}</div></section>`}
function purchasePaid(p){return (p.payments||[]).reduce((sum,pm)=>sum+Number(pm.amount),0)}
function adminTickets(){const purchased=db.purchases.filter(p=>ticketFilter==='all'||(ticketFilter==='unpaid'?purchasePaid(p)<Number(p.price):purchasePaid(p)>=Number(p.price)));const t=db.tickets.filter(t=>who(t.memberId).name.includes(ticketSearch)||t.memberId.includes(ticketSearch));return head('チケット管理','チケット残数・購入・入金状況をまとめて管理します。',`<button class="btn primary" data-action="purchase-new">＋ 購入を登録</button>`)+`<div class="panels"><section class="panel">${section('会員別チケット')}<div class="toolbar"><input class="search" id="ticket-search" placeholder="会員名・IDで検索" value="${attr(ticketSearch)}"></div><div class="item-list">${t.map(x=>`<div class="item"><div class="item-main"><span class="item-icon">▤</span><div><strong>${escapeHTML(who(x.memberId).name)} ・ ${escapeHTML(menu(x.menuId).name)}</strong><small>期限：${x.expires?fullDate(x.expires):'設定なし'} / ${escapeHTML(x.id)}</small></div></div><div class="item-right"><span class="pill-count">${x.remaining}/${x.total}</span><button class="btn soft" data-action="ticket-detail" data-id="${x.id}">編集</button></div></div>`).join('')||'<div class="empty">該当するチケットはありません。</div>'}</div></section><section class="panel">${section('販売メニュー',`<button class="link-btn" data-action="menu-new">追加＋</button>`)}<div class="item-list">${db.menus.map(m=>`<div class="item"><div class="item-main"><span class="item-icon">${m.count||'—'}</span><div><strong>${escapeHTML(m.name)} ${m.hidden?'<span class="badge">非表示</span>':''}</strong><small>${money(m.price)} / ${m.count}回 / ${m.days?m.days+'日':'期限なし'}</small></div></div><button class="btn soft" data-action="menu-detail" data-id="${m.id}">編集</button></div>`).join('')}</div></section></div><section class="panel">${section('購入・入金履歴')}<div class="toolbar"><div class="chips">${[['all','すべて'],['unpaid','未入金・一部入金'],['paid','全額入金']].map(([v,label])=>`<button class="chip ${ticketFilter===v?'active':''}" data-action="ticket-filter" data-filter="${v}">${label}</button>`).join('')}</div></div><div class="tablewrap"><table class="data-table"><thead><tr><th>購入日</th><th>会員名</th><th>メニュー</th><th>対象月</th><th>販売金額</th><th>入金額</th><th>状態</th><th></th></tr></thead><tbody>${purchased.map(p=>`<tr><td>${niceDate(p.date)}</td><td>${escapeHTML(who(p.memberId).name)}</td><td>${escapeHTML(menu(p.menuId).name)}</td><td>${p.targetMonth?escapeHTML(p.targetMonth):'—'}</td><td>${money(p.price)}</td><td>${money(purchasePaid(p))}</td><td>${p.canceled?'<span class="badge bad">取消</span>':purchasePaid(p)>=p.price?'<span class="badge good">入金済</span>':'<span class="badge warn">未完了</span>'}</td><td><button class="btn soft" data-action="purchase-detail" data-id="${p.id}">詳細</button></td></tr>`).join('')||'<tr><td colspan="8">購入記録はありません。</td></tr>'}</tbody></table></div></section>`}
function adminSettings(){return head('設定','営業時間・バックアップ・管理機能の設定を行います。')+`<div class="grid2"><section class="panel">${section('営業時間・予約枠')}<form id="settings-hours"><div class="field-inline"><div class="field"><label>営業時間（開始）</label><input type="time" name="open" step="1800" value="${db.settings.open}"></div><div class="field"><label>営業時間（終了）</label><input type="time" name="close" step="1800" value="${db.settings.close}"></div></div><div class="field"><label>受付締切（セッション開始の何時間前）</label><input type="number" min="0" max="720" name="cutoff" value="${db.settings.bookingCutoff}"></div><p class="note">予約枠の開始は30分刻み、セッション60分固定です。</p><button class="btn primary" type="submit">設定を保存</button></form></section><section class="panel">${section('バックアップ')}<div class="field"><label>自動バックアップ頻度</label><select id="backup-frequency"><option value="daily" ${db.settings.backupFrequency==='daily'?'selected':''}>毎日</option><option value="weekly" ${db.settings.backupFrequency==='weekly'?'selected':''}>毎週</option></select></div><div class="notice">このデモでは自動バックアップは実行されません。頻度設定のみ保存します。本番は別途バックエンドの定期処理が必要です。</div><div class="toolbar"><button class="btn primary" data-action="export-backup">バックアップを書き出す</button><button class="btn" data-action="restore-backup">バックアップから復元</button></div><p class="note">復元は本番ではオーナーのみ。デモは管理者表示のみです。</p></section><section class="panel">${section('システム通知')}<p class="muted small">公開通知、承認通知、予約リマインダーなどを本番で接続予定です。現時点では画面上の通知表示のみ機能します。</p><div class="divider"></div>${section('お知らせ投稿')}<button class="btn" data-action="post-notice">＋ お知らせを作成</button><div class="item-list" style="margin-top:16px">${db.notices.map(n=>`<div class="item"><div class="item-main"><span class="item-icon">✦</span><div><strong>${escapeHTML(n.title)}</strong><small>${niceDate(n.date)}</small></div></div><button class="btn soft" data-action="notice-detail" data-id="${n.id}">編集</button></div>`).join('')}</div></section><section class="panel">${section('管理者・セキュリティ')}<div class="reading"><span>管理者ロール</span><strong>オーナー（デモ）</strong></div><div class="reading"><span>認証方法</span><strong>本番接続前</strong></div><div class="reading"><span>会員LINEログイン</span><strong>未接続</strong></div><p class="note">この画面は認証された管理画面ではありません。実会員情報・実際の決済情報は入力しないでください。</p><button class="btn" data-action="reset-demo">デモデータを初期化</button></section></div>`}
function render(){const html=ROLE==='member'?({home:memberHome,booking:memberBooking,tickets:memberTickets,profile:memberProfile}[tab]||memberHome)():({home:adminHome,booking:adminBooking,members:adminMembers,tickets:adminTickets,settings:adminSettings}[tab]||adminHome)();layout(html)}
function openModal(html){modalHTML=`<div class="modal-head"><span class="eyebrow">SHIFTREX ${ROLE==='admin'?'ADMIN':'MEMBER'}</span><button class="modal-close" data-action="close-modal" aria-label="閉じる">×</button></div>${html}`;render()}
function closeModal(){modalHTML='';render()}
function bookingDetail(id){const b=db.bookings.find(r=>r.id===id);if(!b)return;const admin=ROLE==='admin';openModal(`<h2>予約詳細</h2><div class="pair"><span class="key">予約番号</span><strong>${escapeHTML(b.id)}</strong></div>${admin?`<div class="pair"><span class="key">会員</span><strong>${escapeHTML(who(b.memberId).name)}</strong></div>`:''}<div class="pair"><span class="key">日時</span><strong>${fullDate(b.date)} ${b.time}〜</strong></div><div class="pair"><span class="key">状態</span>${statBadge(b.status)}</div><div class="modal-actions">${admin?b.status==='pending'?`<button class="btn primary" data-action="approve" data-id="${b.id}">承認</button><button class="btn" data-action="decline" data-id="${b.id}">却下</button>`:b.status==='confirmed'?`<button class="btn" data-action="mark-done" data-id="${b.id}">実施済み</button><button class="btn" data-action="mark-absent" data-id="${b.id}">欠席</button><button class="btn danger" data-action="cancel-booking" data-id="${b.id}">予約をキャンセル</button>`:'':b.status==='pending'?`<button class="btn danger" data-action="withdraw" data-id="${b.id}">申請を取り消す</button>`:'<p class="note">確定後の日時変更・キャンセルは管理者のみ可能です。</p>'}<button class="btn" data-action="close-modal">閉じる</button></div>`)}
function selectSlot(time){const date=selectedDate,approval=(db.settings.modeBySlot[`${date} ${time}`]||'instant')==='approval';
const t=usable(memberId,date);if(!t.length){openModal(`<h2>予約できません</h2><p>このセッション日に使用可能なチケットがありません。</p><button class="btn full" data-action="close-modal">閉じる</button>`);return}openModal(`<h2>予約内容の確認</h2><p>以下の内容で${approval?'予約を申請':'予約を確定'}します。</p><div class="pair"><span class="key">日付</span><strong>${fullDate(date)}（${dayName(date)}）</strong></div><div class="pair"><span class="key">時間</span><strong>${time}〜${numToTime(timeToNum(time)+60)}</strong></div><div class="pair"><span class="key">方式</span><strong>${approval?'承認制':'即時確定'}</strong></div><div class="pair"><span class="key">利用予定の券</span><strong>${escapeHTML(menu(t[0].menuId).name)}（残${t[0].remaining}回）</strong></div><div class="modal-actions"><button class="btn" data-action="close-modal">戻る</button><button class="btn primary" data-action="confirm-slot" data-date="${date}" data-time="${time}">${approval?'申請する':'予約を確定する'}</button></div>`)}
function book(date,time){const m=who(memberId);const approval=(db.settings.modeBySlot[`${date} ${time}`]||'instant')==='approval';const n=timeToNum(time);const open=timeToNum(db.settings.open),close=timeToNum(db.settings.close);if(m.status!=='active'||!db.settings.publishedMonths.includes(monthOf(date))||date<TODAY||n<open||n+60>close||n%30!==0||slotConflict(date,time)||isPastCutoff(date,time))return notify('予約できない日時です');const available=usable(memberId,date);if(!available.length)return notify('有効なチケットがありません');const existingPending=db.bookings.filter(b=>b.memberId===memberId&&b.status==='pending').length;const total=db.tickets.filter(t=>validTicket(t,date)&&t.memberId===memberId).reduce((n,t)=>n+t.remaining,0);if(approval&&existingPending>=total)return notify('承認待ち申請数がチケット残数の上限です');const b={id:uid('RES'),memberId,date,time,status:approval?'pending':'confirmed',ticketId:approval?null:available[0].id};if(!approval)available[0].remaining--;db.bookings.push(b);log('予約登録',`${m.name} ${date} ${time} ${b.status}`);save();modalHTML='';notify(approval?'予約申請を受け付けました':'予約が確定しました')}
function approve(id){let b=db.bookings.find(x=>x.id===id);if(!b||b.status!=='pending')return; if(slotConflict(b.date,b.time,b.id)){notify('他の確定予約と重なるため承認できません');return;}let ts=usable(b.memberId,b.date);if(!ts.length){notify('実施日に有効なチケットがありません');return;}b.status='confirmed';b.ticketId=ts[0].id;ts[0].remaining--;db.bookings.forEach(x=>{if(x.id!==b.id&&x.status==='pending'&&x.date===b.date&&timeToNum(x.time)<timeToNum(b.time)+60&&timeToNum(x.time)+60>timeToNum(b.time))x.status='declined'});log('予約承認',`${who(b.memberId).name} ${b.date} ${b.time}`);save();modalHTML='';notify('予約を承認しました')}
function decline(id){const b=db.bookings.find(x=>x.id===id);if(!b||b.status!=='pending')return;openModal(`<h2>予約申請の却下</h2><p>${escapeHTML(who(b.memberId).name)} / ${fullDate(b.date)} ${b.time}</p><form id="decline-form" data-id="${b.id}"><div class="field"><label>却下理由（任意）</label><textarea name="reason" placeholder="理由を入力できます"></textarea></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">戻る</button><button type="submit" class="btn danger">却下する</button></div></form>`)}
function withdraw(id){const b=db.bookings.find(x=>x.id===id);if(!b||b.status!=='pending'||ROLE!=='member')return;b.status='withdrawn';log('申請取消',`${who(b.memberId).name} ${b.date} ${b.time}`);save();modalHTML='';notify('申請を取り消しました')}
function bookingState(id,newStatus){let b=db.bookings.find(x=>x.id===id);if(!b||b.status!=='confirmed')return;if(newStatus==='cancel'){openModal(`<h2>確定予約のキャンセル</h2><p>チケットの取り扱いを選択してください。</p><form id="cancel-booking-form" data-id="${b.id}"><div class="field"><label>チケット処理</label><select name="returnTicket"><option value="yes">チケットを返却する</option><option value="no">チケットを消化したままにする</option></select></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">戻る</button><button class="btn danger" type="submit">キャンセルを確定</button></div></form>`);return}if(newStatus==='absent'){openModal(`<h2>欠席の登録</h2><p>欠席時のチケット処理を選択してください。</p><form id="absent-form" data-id="${b.id}"><div class="field"><label>チケット処理</label><select name="returnTicket"><option value="no">チケットを消化したままにする</option><option value="yes">チケットを返却する</option></select></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">戻る</button><button class="btn primary" type="submit">欠席として記録</button></div></form>`);return}b.status='done';log('セッション実施',`${who(b.memberId).name} ${b.date} ${b.time}`);save();modalHTML='';notify('実施済みに変更しました')}
function requestChange(){const m=who(memberId),ch=db.changes.find(c=>c.memberId===memberId&&c.status==='pending');openModal(`<h2>連絡先の変更申請</h2><p>管理者の承認後、登録情報に反映されます。</p><form id="change-request"><div class="field"><label>電話番号</label><input name="phone" required maxlength="30" value="${attr(ch?ch.phone:m.phone)}"></div><div class="field"><label>メールアドレス</label><input name="email" type="email" required maxlength="200" value="${attr(ch?ch.email:m.email)}"></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">戻る</button><button type="submit" class="btn primary">変更を申請</button></div></form>`)}
function reviewChange(id){let c=db.changes.find(c=>c.id===id);if(!c)return;openModal(`<h2>連絡先変更申請</h2><div class="pair"><span class="key">会員</span><strong>${escapeHTML(who(c.memberId).name)}</strong></div><div class="pair"><span class="key">新しい電話番号</span><strong>${escapeHTML(c.phone)}</strong></div><div class="pair"><span class="key">新しいメール</span><strong>${escapeHTML(c.email)}</strong></div><div class="modal-actions"><button class="btn primary" data-action="change-approve" data-id="${c.id}">承認</button><button class="btn danger" data-action="change-decline" data-id="${c.id}">却下</button></div>`)}
function memberDetail(id){let m=who(id),ts=db.tickets.filter(x=>x.memberId===id),bs=sortBookings(db.bookings.filter(x=>x.memberId===id));openModal(`<h2>${escapeHTML(m.name)}</h2><p>${escapeHTML(m.id)}　${memberBadge(m.status)}</p><div class="pair"><span class="key">フリガナ</span><strong>${escapeHTML(m.kana)}</strong></div><div class="pair"><span class="key">電話番号</span><strong>${escapeHTML(m.phone)}</strong></div><div class="pair"><span class="key">メール</span><strong>${escapeHTML(m.email)}</strong></div><div class="divider"></div><h3 class="section-title">チケット</h3>${ts.map(t=>`<div class="reading"><span>${escapeHTML(menu(t.menuId).name)}</span><strong>残${t.remaining}/${t.total}回</strong></div>`).join('')||'<p class="note">なし</p>'}<div class="divider"></div><h3 class="section-title">予約</h3>${bs.slice(0,6).map(b=>`<div class="reading"><span>${niceDate(b.date)} ${b.time}</span>${statBadge(b.status)}</div>`).join('')||'<p class="note">なし</p>'}<div class="divider"></div><form id="member-status-form" data-id="${m.id}"><div class="field"><label>会員状態</label><select name="status"><option value="active" ${m.status==='active'?'selected':''}>在籍</option><option value="paused" ${m.status==='paused'?'selected':''}>休会</option><option value="left" ${m.status==='left'?'selected':''}>退会</option></select></div><button class="btn" type="submit">状態を変更</button></form><div class="modal-actions"><button class="btn" data-action="close-modal">閉じる</button></div>`)}
function createMember(){openModal(`<h2>会員を登録</h2><p>デモ用の氏名のみ登録できます。実在する個人情報は入力しないでください。</p><form id="member-create"><div class="field"><label>氏名（サンプル）</label><input name="name" maxlength="50" required placeholder="例：テスト 会員"></div><div class="field"><label>フリガナ</label><input name="kana" maxlength="60" placeholder="テスト カイイン"></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">戻る</button><button type="submit" class="btn primary">登録</button></div></form>`)}
function createBooking(){openModal(`<h2>管理者による予約登録</h2><form id="admin-booking-form"><div class="field"><label>会員</label><select name="memberId">${db.members.filter(m=>m.status==='active').map(m=>`<option value="${m.id}">${escapeHTML(m.name)}</option>`).join('')}</select></div><div class="field-inline"><div class="field"><label>日付</label><input name="date" type="date" min="${TODAY}" value="${selectedDate<TODAY?TODAY:selectedDate}" required></div><div class="field"><label>開始時刻</label><input name="time" type="time" step="1800" value="10:00" required></div></div><p class="note">チケットがある会員だけ予約を作成できます。例外的な無券予約は本番実装時に対応します。</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">戻る</button><button class="btn primary" type="submit">予約を確定</button></div></form>`)}
function purchaseNew(){openModal(`<h2>購入を登録</h2><p>購入額・対象月・入金額を入力します。※実際の決済は行いません。</p><form id="purchase-new-form"><div class="field"><label>会員</label><select name="memberId">${db.members.filter(m=>m.status!=='left').map(m=>`<option value="${m.id}">${escapeHTML(m.name)}</option>`).join('')}</select></div><div class="field"><label>購入メニュー</label><select name="menuId" id="purchase-menu">${db.menus.filter(m=>!m.hidden).map(m=>`<option value="${m.id}">${escapeHTML(m.name)}　${money(m.price)}</option>`).join('')}</select></div><div class="field-inline"><div class="field"><label>購入日</label><input name="date" type="date" required value="${TODAY}"></div><div class="field"><label>販売価格（円）</label><input name="price" id="purchase-price" type="number" min="0" step="1" required value="${db.menus.filter(m=>!m.hidden)[0]?.price||0}"></div></div><div id="month-field"></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">戻る</button><button type="submit" class="btn primary">購入を登録</button></div></form>`);updateMonthField()}
function updateMonthField(){let s=$('purchase-menu');if(!s)return;let mm=menu(s.value),target=$('month-field');if(target)target.innerHTML=mm.monthRequired?`<div class="field"><label>対象月（必須）</label><input type="month" name="targetMonth" value="${monthOf(TODAY)}" required></div>`:''}
function purchaseDetail(id){let p=db.purchases.find(x=>x.id===id);if(!p)return;let mm=menu(p.menuId),paid=purchasePaid(p);openModal(`<h2>購入詳細</h2><p>${escapeHTML(who(p.memberId).name)} ・ ${escapeHTML(mm.name)} / ${escapeHTML(p.id)}</p><div class="pair"><span class="key">登録金額</span><strong>${money(p.price)}</strong></div><div class="pair"><span class="key">入金額</span><strong>${money(paid)}</strong></div><div class="pair"><span class="key">未入金</span><strong>${money(Math.max(0,p.price-paid))}</strong></div><div class="pair"><span class="key">チケット</span><strong>${p.issuedTicketId?'発行済み':'未発行'}</strong></div><div class="divider"></div><form id="purchase-edit-form" data-id="${p.id}"><div class="field-inline"><div class="field"><label>購入日</label><input name="date" type="date" required value="${attr(p.date)}"></div><div class="field"><label>販売金額</label><input name="price" type="number" min="0" step="1" value="${p.price}" required></div></div>${mm.monthRequired?`<div class="field"><label>対象月（必須）</label><input name="targetMonth" type="month" required value="${attr(p.targetMonth)}"></div>`:''}<button class="btn primary" type="submit">購入情報を変更</button></form><div class="divider"></div><h3 class="section-title">入金履歴</h3>${(p.payments||[]).map(x=>`<div class="reading"><span>${niceDate(x.date)} / ${escapeHTML(x.method)}</span><strong>${money(x.amount)}</strong></div>`).join('')||'<p class="note">入金履歴はありません。</p>'}<form id="payment-form" data-id="${p.id}"><div class="field-inline"><div class="field"><label>入金日</label><input name="date" type="date" required value="${TODAY}"></div><div class="field"><label>入金額（円）</label><input name="amount" type="number" step="1" min="1" required placeholder="例：8000"></div></div><div class="field"><label>入金方法</label><select name="method"><option>現金</option><option>銀行振込</option><option>クレジットカード</option><option>その他</option></select></div><button class="btn" type="submit">入金を登録</button></form><p class="note">デモでは入金の修正・取消・預かり金管理は未実装です。</p><div class="modal-actions"><button class="btn" data-action="close-modal">閉じる</button></div>`)}
function issueTicket(p){if(p.issuedTicketId||p.canceled||purchasePaid(p)<p.price)return;let mm=menu(p.menuId);if(mm.count===0)return;let days=mm.days?Number(mm.days):0;let ts={id:uid('TK'),memberId:p.memberId,menuId:mm.id,total:Number(mm.count),remaining:Number(mm.count),purchased:p.date,expires:days?addDays(p.date,days-1):null,source:p.id};db.tickets.push(ts);p.issuedTicketId=ts.id;log('チケット自動発行',`${who(p.memberId).name} ${mm.name} ${ts.total}回`)}
function ticketDetail(id){const t=db.tickets.find(x=>x.id===id);if(!t)return;openModal(`<h2>チケットの編集</h2><p>${escapeHTML(who(t.memberId).name)} ・ ${escapeHTML(menu(t.menuId).name)}</p><form id="ticket-edit-form" data-id="${t.id}"><div class="field-inline"><div class="field"><label>残回数</label><input type="number" name="remaining" required min="0" max="${t.total}" value="${t.remaining}"></div><div class="field"><label>有効期限</label><input type="date" name="expires" value="${attr(t.expires||'')}"></div></div><div class="field"><label>購入日</label><input type="date" name="purchased" value="${attr(t.purchased)}" required></div><p class="note">購入日を変更すると、設定済み有効日数で期限を再計算します。影響する予約・申請がある場合は警告します。</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">戻る</button><button class="btn primary" type="submit">変更を保存</button></div></form>`)}
function menuDetail(id){const m=db.menus.find(x=>x.id===id),newOne=!m;openModal(`<h2>${newOne?'メニューを追加':'メニューを編集'}</h2><form id="menu-form" data-id="${m?.id||''}"><div class="field"><label>メニュー名</label><input name="name" required maxlength="80" value="${attr(m?.name||'')}"></div><div class="field-inline"><div class="field"><label>販売基準価格（円）</label><input name="price" type="number" min="0" step="1" required value="${m?.price||0}"></div><div class="field"><label>発行回数（0可）</label><input name="count" type="number" min="0" max="1000" required value="${m?.count||0}"></div></div><div class="field-inline"><div class="field"><label>有効日数（0＝無期限）</label><input name="days" type="number" min="0" max="3650" required value="${m?.days||0}"></div><div class="field"><label>対象月入力</label><select name="monthRequired"><option value="no" ${!m?.monthRequired?'selected':''}>OFF</option><option value="yes" ${m?.monthRequired?'selected':''}>ON・必須</option></select></div></div><div class="field"><label>新規購入への表示</label><select name="hidden"><option value="no" ${!m?.hidden?'selected':''}>表示</option><option value="yes" ${m?.hidden?'selected':''}>非表示</option></select></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">戻る</button><button class="btn primary" type="submit">${newOne?'追加':'変更を保存'}</button></div></form>`)}
function noticeDetail(id){let n=db.notices.find(n=>n.id===id);openModal(`<h2>${n?'お知らせを編集':'お知らせを投稿'}</h2><form id="notice-form" data-id="${n?.id||''}"><div class="field"><label>見出し</label><input name="title" required maxlength="80" value="${attr(n?.title||'')}"></div><div class="field"><label>本文</label><textarea name="body" required maxlength="1200">${escapeHTML(n?.body||'')}</textarea></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">戻る</button><button type="submit" class="btn primary">保存</button></div></form>`)}
function showAlerts(){const pending=db.bookings.filter(b=>b.status==='pending');openModal(`<h2>お知らせ・通知</h2>${ROLE==='admin'?`<p>予約の承認待ち：${pending.length}件 / 連絡先変更申請：${db.changes.filter(c=>c.status==='pending').length}件</p>${pending.map(b=>`<div class="reading"><span>${escapeHTML(who(b.memberId).name)} ${niceDate(b.date)} ${b.time}</span><span class="badge warn">承認待ち</span></div>`).join('')}`:db.notices.map(n=>`<div class="reading"><span>${escapeHTML(n.title)}</span><span class="muted">${niceDate(n.date)}</span></div>`).join('')}<div class="modal-actions"><button class="btn" data-action="close-modal">閉じる</button></div>`)}
function exportBackup(){const data={application:'SHIFTREX',version:VERSION,exportedAt:new Date().toISOString(),data:db};let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`shiftrex-demo-backup-${TODAY}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);log('バックアップ','手動書き出し（ブラウザー内デモ）');save();notify('バックアップファイルを書き出しました')}
function restoreBackup(){openModal(`<h2>デモデータの復元</h2><p>オーナーのみを想定した復元画面です。JSONファイルから全体または種類別に復元します。</p><div class="notice">復元すると現在のデモデータが上書きされます。事前にバックアップを書き出してください。</div><form id="restore-form"><div class="field"><label>バックアップJSONファイル</label><input name="file" type="file" accept="application/json,.json" required></div><div class="field"><label>復元範囲</label><select name="type"><option value="all">すべて復元</option><option value="members">会員情報のみ</option><option value="bookings">予約情報のみ</option><option value="tickets">チケット情報のみ</option><option value="purchases">購入・入金情報のみ</option><option value="settings">設定のみ</option><option value="notices">お知らせのみ</option></select></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">戻る</button><button class="btn danger" type="submit">復元内容を確認</button></div></form>`)}
function validRestore(src,type){if(!src||src.version!==VERSION||!Array.isArray(src.members)||!Array.isArray(src.bookings)||!Array.isArray(src.tickets)||!Array.isArray(src.purchases)||!src.settings||!Array.isArray(src.menus)||!Array.isArray(src.notices))return false;const result=type==='all'?structuredClone(src):structuredClone(db);if(type!=='all'){if(!Object.prototype.hasOwnProperty.call(src,type))return false;result[type]=structuredClone(src[type]);}const members=new Set(result.members.map(x=>x.id)),tickets=new Set(result.tickets.map(x=>x.id));if(result.bookings.some(b=>!members.has(b.memberId)||(b.ticketId&&!tickets.has(b.ticketId))))return false;if(result.tickets.some(t=>!members.has(t.memberId)))return false;if(result.purchases.some(p=>!members.has(p.memberId)||(p.issuedTicketId&&!tickets.has(p.issuedTicketId))))return false;return true}
function doAction(action,data){const id=data.id;switch(action){case'close-modal':closeModal();break;case'show-alerts':showAlerts();break;case'select-day':selectedDate=data.date;viewMonth=monthOf(selectedDate);render();break;case'previous-month':moveMonth(-1);render();break;case'next-month':moveMonth(1);render();break;case'calendar-view':calendarView=data.view;render();break;case'admin-view':adminView=data.view;render();break;case'select-slot':selectSlot(data.time);break;case'confirm-slot':book(data.date,data.time);break;case'booking-detail':bookingDetail(id);break;case'approve':approve(id);break;case'decline':decline(id);break;case'withdraw':withdraw(id);break;case'mark-done':bookingState(id,'done');break;case'mark-absent':bookingState(id,'absent');break;case'cancel-booking':bookingState(id,'cancel');break;case'request-change':requestChange();break;case'cancel-change':db.changes.forEach(c=>{if(c.memberId===memberId&&c.status==='pending')c.status='withdrawn'});log('変更申請取消',who(memberId).name);save();notify('変更申請を取り消しました');break;case'review-change':reviewChange(id);break;case'change-approve':case'change-decline':{let c=db.changes.find(c=>c.id===id);if(c){if(action==='change-approve'){who(c.memberId).phone=c.phone;who(c.memberId).email=c.email;}c.status=action==='change-approve'?'approved':'declined';log('連絡先申請の処理',`${who(c.memberId).name} ${c.status}`);save();modalHTML='';notify(action==='change-approve'?'変更を承認しました':'変更を却下しました')}break;}case'member-filter':memberFilter=data.filter;render();break;case'ticket-filter':ticketFilter=data.filter;render();break;case'member-detail':memberDetail(id);break;case'create-member':createMember();break;case'create-booking':createBooking();break;case'purchase-new':purchaseNew();break;case'purchase-detail':purchaseDetail(id);break;case'ticket-detail':ticketDetail(id);break;case'menu-new':menuDetail(null);break;case'menu-detail':menuDetail(id);break;case'post-notice':noticeDetail(null);break;case'notice-detail':noticeDetail(id);break;case'export-backup':exportBackup();break;case'restore-backup':restoreBackup();break;case'reset-demo':openModal(`<h2>デモデータの初期化</h2><p>このブラウザー内のサンプル操作内容を初期状態に戻します。</p><div class="modal-actions"><button class="btn" data-action="close-modal">戻る</button><button class="btn danger" data-action="confirm-reset">初期化する</button></div>`);break;case'confirm-reset':db=seed();save();modalHTML='';notify('デモを初期化しました');break;case'toggle-publication':{let m=monthOf(selectedDate),set=db.settings.publishedMonths;db.settings.publishedMonths=set.includes(m)?set.filter(x=>x!==m):[...set,m];log('予約枠公開変更',m);save();notify(set.includes(m)?'月の公開を取り消しました':'予約枠の公開状態を変更しました');break;}case'toggle-mode':{let key=`${selectedDate} ${data.time}`;db.settings.modeBySlot[key]=db.settings.modeBySlot[key]==='approval'?'instant':'approval';save();render();break;}default:break;}}
async function submitForm(f){let fd=new FormData(f),get=k=>String(fd.get(k)||'').trim(),id=f.dataset.id;switch(f.id){case'change-request':{let ch=db.changes.find(c=>c.memberId===memberId&&c.status==='pending');if(ch){ch.phone=get('phone');ch.email=get('email')}else db.changes.push({id:uid('CHG'),memberId,phone:get('phone'),email:get('email'),status:'pending'});log('連絡先変更申請',who(memberId).name);save();modalHTML='';notify('連絡先の変更を申請しました');break;}case'decline-form':{let b=db.bookings.find(x=>x.id===id);if(b&&b.status==='pending'){b.status='declined';b.reason=get('reason');log('予約申請却下',`${who(b.memberId).name} ${b.date}`);save();modalHTML='';notify('申請を却下しました')}break;}case'cancel-booking-form':case'absent-form':{let b=db.bookings.find(x=>x.id===id);if(!b||b.status!=='confirmed')break;b.status=f.id==='absent-form'?'absent':'canceled';if(get('returnTicket')==='yes'){let t=db.tickets.find(t=>t.id===b.ticketId);if(t)t.remaining=Math.min(t.total,t.remaining+1)}log('予約処理',`${who(b.memberId).name} ${b.status}`);save();modalHTML='';notify('予約の状態を変更しました');break;}case'member-create':{let next=Math.max(0,...db.members.map(m=>Number(m.id.split('-')[1])||0))+1,m={id:`STX-${String(next).padStart(4,'0')}`,name:get('name'),kana:get('kana'),status:'active',phone:'未登録',email:'未登録',joined:TODAY};db.members.push(m);log('会員登録',m.id);save();modalHTML='';notify('サンプル会員を登録しました');break;}case'member-status-form':{let m=who(id),status=get('status');if((status==='paused'||status==='left')&&activeBookings(id).length)return notify('予約・申請があるため、この状態に変更できません');m.status=status;log('会員状態変更',`${m.name} → ${status}`);save();modalHTML='';notify('会員状態を変更しました');break;}case'admin-booking-form':{let mid=get('memberId'),date=get('date'),time=get('time'),n=timeToNum(time),ts=usable(mid,date);if(!ts.length||slotConflict(date,time)||n%30!==0||n<timeToNum(db.settings.open)||n+60>timeToNum(db.settings.close)||date<TODAY)return notify('予約不可：日時の重複または有効な券がありません');ts[0].remaining--;db.bookings.push({id:uid('RES'),memberId:mid,date,time,status:'confirmed',ticketId:ts[0].id});log('管理者予約登録',`${who(mid).name} ${date} ${time}`);save();modalHTML='';notify('管理者予約を登録しました');break;}case'purchase-new-form':{let m=menu(get('menuId')),price=+get('price'),date=get('date'),tm=get('targetMonth'),mid=get('memberId');if(price<0||!Number.isFinite(price)||m.monthRequired&&!tm)return notify('販売金額・対象月を確認してください');if(m.monthRequired&&db.purchases.some(p=>p.memberId===mid&&p.menuId===m.id&&p.targetMonth===tm&&!p.canceled)&&!window.confirm('同じ会員・対象月の購入が登録済みです。重複登録を続行しますか？'))return;let p={id:uid('PUR'),memberId:mid,menuId:m.id,date,price,targetMonth:tm,payments:[],canceled:false,issuedTicketId:null};db.purchases.unshift(p);if(price===0)issueTicket(p);log('購入登録',`${who(mid).name} ${m.name} ${money(price)}`);save();modalHTML='';notify('購入を登録しました');break;}case'payment-form':{let p=db.purchases.find(p=>p.id===id),amount=+get('amount');if(!p||amount<=0||!Number.isFinite(amount))return notify('入金額を確認してください');p.payments.push({id:uid('PMT'),date:get('date'),amount,method:get('method')});issueTicket(p);log('入金登録',`${who(p.memberId).name} ${money(amount)}`);save();modalHTML='';notify('入金を登録しました');break;}case'purchase-edit-form':{let p=db.purchases.find(x=>x.id===id);if(!p)break;let m=menu(p.menuId),date=get('date'),price=+get('price'),targetMonth=get('targetMonth');if(price<0||m.monthRequired&&!targetMonth)return notify('入力内容を確認してください');if(m.monthRequired&&db.purchases.some(x=>x.id!==p.id&&x.memberId===p.memberId&&x.menuId===p.menuId&&x.targetMonth===targetMonth&&!x.canceled)&&!window.confirm('対象月が重複しています。このまま変更しますか？'))return;const t=db.tickets.find(x=>x.id===p.issuedTicketId);if(t&&date!==p.date&&m.days){let newExp=addDays(date,m.days-1);if(newExp<t.expires&&db.bookings.some(b=>(b.ticketId===t.id||(b.status==='pending'&&b.memberId===p.memberId))&&b.date>newExp&&['confirmed','pending'].includes(b.status))&&!window.confirm('有効期限外になる予約・申請があります。予約は維持して変更しますか？'))return;t.purchased=date;t.expires=newExp;}p.date=date;p.price=price;p.targetMonth=targetMonth;issueTicket(p);log('購入情報編集',p.id);save();modalHTML='';notify('購入情報を更新しました');break;}case'ticket-edit-form':{let t=db.tickets.find(t=>t.id===id);if(!t)break;let rm=+get('remaining'),date=get('purchased'),exp=get('expires')||null,mm=menu(t.menuId);if(rm<0||rm>t.total)return notify('残回数の範囲を確認してください');if(date!==t.purchased&&mm.days)exp=addDays(date,mm.days-1);if(exp&&t.expires&&exp<t.expires&&db.bookings.some(b=>(b.ticketId===t.id||(b.status==='pending'&&b.memberId===t.memberId))&&b.date>exp&&['confirmed','pending'].includes(b.status))&&!window.confirm('有効期限外になる確定予約があります。予約を維持して変更しますか？'))return;t.remaining=rm;t.purchased=date;t.expires=exp;log('チケット編集',`${t.id} 期限${exp}`);save();modalHTML='';notify('チケットを更新しました');break;}case'menu-form':{let m=db.menus.find(m=>m.id===id),v={name:get('name'),price:+get('price'),count:+get('count'),days:+get('days'),monthRequired:get('monthRequired')==='yes',hidden:get('hidden')==='yes'};if(Object.values(v).some(x=>typeof x==='number'&&(!Number.isFinite(x)||x<0)))return notify('数値を確認してください');if(m)Object.assign(m,v);else db.menus.push({id:uid('menu'),...v});log('販売メニュー編集',v.name);save();modalHTML='';notify('メニューを保存しました');break;}case'notice-form':{let n=db.notices.find(x=>x.id===id);if(n){n.title=get('title');n.body=get('body')}else db.notices.unshift({id:uid('N'),title:get('title'),body:get('body'),date:TODAY});log('お知らせ保存',get('title'));save();modalHTML='';notify('お知らせを保存しました');break;}case'settings-hours':{let a=get('open'),b=get('close');if(timeToNum(a)>=timeToNum(b)||timeToNum(a)%30||timeToNum(b)%30)return notify('営業時間を30分単位で設定してください');db.settings.open=a;db.settings.close=b;db.settings.bookingCutoff=+get('cutoff');log('営業時間編集',`${a}〜${b}`);save();notify('設定を保存しました');break;}case'restore-form':{let file=f.querySelector('input[type="file"]').files?.[0];if(!file)return;let obj;try{obj=JSON.parse(await file.text())}catch(e){notify('JSONファイルを読み込めません');return}let source=obj.data,type=get('type');if(!validRestore(source,type)){notify('不正なファイル、または関連データが整合しません');return}pendingRestore={source,type};openModal(`<h2>復元の最終確認</h2><div class="notice">${type==='all'?'全データ':'「'+escapeHTML(type)+'」のデータ'}をバックアップ内容で上書きします。現在のデモ操作内容が失われる可能性があります。</div><div class="modal-actions"><button class="btn" data-action="close-modal">戻る</button><button class="btn danger" data-action="confirm-restore">復元を実行</button></div>`);break;}}}
const originalAction=doAction;
function handlerAction(action,data){if(action==='confirm-restore'&&pendingRestore){let {source,type}=pendingRestore;const original=structuredClone(db);if(type==='all')db=structuredClone(source);else db[type]=structuredClone(source[type]);if(!validRestore(db,'all')){db=original;return notify('復元後のデータ検証に失敗しました')}db.version=VERSION;log('データ復元',type);save();pendingRestore=null;modalHTML='';notify('デモのバックアップを復元しました');return}originalAction(action,data)}
document.addEventListener('click',e=>{const tabEl=e.target.closest('[data-tab]');if(tabEl){setTab(tabEl.dataset.tab);return}const a=e.target.closest('[data-action]');if(a){e.preventDefault();handlerAction(a.dataset.action,a.dataset);return}if(e.target.dataset.backdrop){closeModal()}});
document.addEventListener('submit',e=>{if(e.target instanceof HTMLFormElement){e.preventDefault();submitForm(e.target).catch(err=>{console.error(err);notify('操作を完了できませんでした')})}});
document.addEventListener('input',e=>{if(e.target.id==='member-search'){let v=e.target.value,at=e.target.selectionStart;memberSearch=v;render();let el=$('member-search');if(el){el.focus();el.setSelectionRange(at,at)}}else if(e.target.id==='ticket-search'){let v=e.target.value,at=e.target.selectionStart;ticketSearch=v;render();let el=$('ticket-search');if(el){el.focus();el.setSelectionRange(at,at)}}});
document.addEventListener('change',e=>{if(e.target.id==='purchase-menu'){$('purchase-price').value=menu(e.target.value).price;updateMonthField()}if(e.target.id==='backup-frequency'){db.settings.backupFrequency=e.target.value;save();notify('バックアップ頻度の設定を保存しました（デモ）')}});
let touchStart=null;document.addEventListener('touchstart',e=>{if(e.target.closest('.tabs'))touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY};else touchStart=null},{passive:true});document.addEventListener('touchend',e=>{if(!touchStart)return;let dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;if(Math.abs(dx)>42&&Math.abs(dy)<35){let tabs=(ROLE==='admin'?navAdmin:navMember).map(x=>x[0]),next=Math.max(0,Math.min(tabs.length-1,tabs.indexOf(tab)+(dx<0?1:-1)));setTab(tabs[next])}touchStart=null},{passive:true});
window.addEventListener('storage',e=>{if(e.key===KEY){db=read();render()}});
render();
})();
